// Loaded by every page: shared styles plus the service worker that makes the collection work
// offline. The worker (generated by vite-plugin-pwa) precaches the whole build; when a deploy
// lands it installs in the background and open pages reload onto the new version.
import './base.css';
import { Workbox } from 'workbox-window';
import { trackViewportHeight } from './viewport';
import { keepScreenOn } from './wakelock';

trackViewportHeight();
// Game pages keep the screen from dimming while they're played (not the launcher).
if (document.body?.classList.contains('game')) keepScreenOn();

if ('serviceWorker' in navigator && import.meta.env.PROD) {
  // This module is built into assets/, so the site root (where sw.js lives) is one level up.
  // Resolved from the script rather than the page so it works from every game's folder.
  const root = import.meta.url.replace(/assets\/[^/]*$/, '');
  const wb = new Workbox(`${root}sw.js`, { scope: root });
  wb.addEventListener('controlling', (event) => {
    if (event.isUpdate) location.reload();
  });
  wb.register().catch((err) => console.warn('Service worker registration failed:', err));

  // The pre-build service worker cached everything under this name; Workbox doesn't know about it.
  caches.delete('games-v1').catch(() => {});
}
